#include <vector>
#include <algorithm>
#include <stack>

using namespace std;

const int MAX_NODES = 100;
vector<vector<int>> G(MAX_NODES);

int iterativeRec(int start) {
    vector<bool> used(MAX_NODES, false);
    stack<pair<int, int>> stk; // pair of current node and depth
    stk.push({start, 1});
    int maxDepth = 0;

    while (!stk.empty()) {
        auto [node, depth] = stk.top();
        stk.pop();

        if (used[node]) continue;
        used[node] = true;
        maxDepth = max(maxDepth, depth);

        for (int neighbor : G[node]) {
            if (!used[neighbor]) {
                stk.push({neighbor, depth + 1});
            }
        }
    }
    return maxDepth;
}

int main() {
    int N, A, B;

    while (cin >> N, N) {
        G.assign(MAX_NODES, vector<int>());

        for (int i = 0; i < N; i++) {
            cin >> A >> B;
            G[--A].push_back(--B);
            G[B].push_back(A);
        }

        int ret = 0;
        for (int i = 0; i < MAX_NODES; i++) {
            if (!G[i].empty()) {
                ret = max(ret, iterativeRec(i));
            }
        }

        cout << ret << endl;
    }

    return 0;
}

